                          solution: 'A. 凝结（放热）——空气中的水蒸气遇冷液化成小水滴；B. 凝华（放热）——室内水蒸气遇冷直接变成固态冰晶；C. 蒸发（吸热）——水变成水蒸气散发到空气中。',
