                          solution: '昆虫：蚂蚁、蜜蜂、蜻蜓（身体分头胸腹三部分，6 条腿，有触角）。不是昆虫：蜘蛛（8 条腿，身体分两部分，蛛形纲）；蜈蚣（很多条腿，多足纲）；蜗牛（软体动物，没有分节的足）。',
                          tip: '判断三步法：①数腿——是不是 6 条？②看身体——是不是头胸腹三部分？③看触角——有没有 1 对？三个都满足才是昆虫。'
