                          solution: '蝴蝶是完全变态（有蛹期，幼虫毛毛虫和成虫蝴蝶样子完全不同）；蝗虫是不完全变态（没有蛹期，若虫和成虫外形相似，只是个头小、翅膀没长全）。',
