                        { question: '填空题：昆虫的身体分为______、______、______三部分，胸部有______对足，一般有______对翅。', answer: '头、胸、腹；3（三）；2（两）', explanation: '昆虫的共同特征：身体分头胸腹三部分，胸部着生 3 对足（6 条腿），大多数有 2 对翅。' },
                        { question: '简答题：蜘蛛有 8 条腿，蜈蚣有很多条腿，它们都不是昆虫。请从身体结构的角度说明为什么它们不是昆虫。', answer: '蜘蛛身体分为头胸部和腹部两部分（不是三部分），有 8 条腿（4 对），没有触角，不符合昆虫特征；蜈蚣身体由许多体节组成，每节有 1-2 对足，足的数量远超过 3 对，身体也不分头胸腹三部分，不符合昆虫特征。', explanation: '昆虫的关键特征是：身体分头胸腹三部分 + 3 对足 + 1 对触角。蜘蛛和蜈蚣都不满足这些条件，所以都不是昆虫。' }
