                      explanation: `青蛙是我们在生活中最常见的两栖动物。它们小时候是蝌蚪，长大后变成青蛙，这个变化过程非常神奇！

**两栖类的共同特征**

两栖动物最特别的地方是它们一生要经历**两种生活方式**：

- **幼体（蝌蚪）**：生活在**水中**，用**鳃**呼吸，有尾巴，没有腿
- **成体（青蛙）**：可以在**陆地**生活，用**肺**呼吸，有四肢，尾巴消失

这种从幼体到成体形态和生活方式发生巨大变化的过程，叫做**变态发育**。

**青蛙的变态发育过程**

1. **卵**：青蛙在水里产下卵，卵外包着一层胶状物质
2. **蝌蚪**：卵孵化出蝌蚪，像小鱼一样用鳃呼吸，有长尾巴
3. **长出后腿**：蝌蚪先长出后腿
4. **长出前腿**：再长出前腿，尾巴逐渐缩短
5. **幼蛙**：尾巴完全消失，变成小青蛙，开始用肺呼吸
6. **成蛙**：发育成熟，可以水陆两栖生活

**两栖动物的皮肤会"呼吸"**

两栖动物的皮肤**裸露、湿润**，没有鳞片和毛发覆盖。皮肤下面有丰富的毛细血管，能**辅助呼吸**。所以两栖动物必须保持皮肤湿润，否则就无法呼吸了！这也是它们不能完全离开水的原因之一。

**常见的两栖动物**

- **青蛙**：绿色或褐色，善于跳跃和游泳
- **蟾蜍（癞蛤蟆）**：皮肤粗糙有疙瘩，不善跳跃但能走路
- **蝾螈（火蜥蜴）**：外形像蜥蜴但有尾巴和湿润皮肤
- **大鲵（娃娃鱼）**：中国特有的珍稀两栖动物，体长可达 1 米以上

**两栖动物不是爬行动物！**

两栖动物和爬行动物容易混淆，关键区别：

- **两栖动物**：皮肤裸露湿润、幼体水生用鳃、变态发育
- **爬行动物**（如蛇、乌龟）：体表有鳞片或甲、终生用肺呼吸、不经过变态发育`,
