                      objectives: [
                        '能说出水在自然界有三种状态：固态（冰）、液态（水）、气态（水蒸气）',
                '理解水的循环过程：蒸发→凝结→降水→径流',
                        '知道水循环使地球上的水资源得以不断更新和流动',
                '了解水资源的珍贵，知道节约用水的方法'
                      ],
                      explanation: `水在自然界中不停地运动着，从海洋到天空、从天空到陆地、再从陆地回到海洋。这个永不停息的过程叫做**水循环**。

**水的三种状态**

- **固态**：冰、雪、霜、冰雹——有固定形状和体积
- **液态**：水、雨、雾——有固定体积，没有固定形状
- **气态**：水蒸气——没有固定形状和体积（水蒸气是看不见的！我们看到的"白气"是细小的小水滴）

**水循环的过程**

1. **蒸发**：太阳照射使海洋、河流、湖泊中的水变成水蒸气，升到空中。植物也会通过叶片蒸腾水分
2. **凝结**：水蒸气在高空遇冷凝结成小水滴，大量小水滴聚集形成**云**
3. **降水**：云中的小水滴越聚越大，当空气托不住时，就会落下来成为**雨**（或雪、冰雹）
4. **径流**：落到地面的水，一部分渗入地下成为地下水，一部分沿地面流入河流，最终回到海洋

如此循环往复，永不停息！

**水循环的意义**

- 使地球上的水**不断更新**，保持新鲜
- 把水从海洋送到陆地，提供淡水资源
- 调节地球气候，影响天气变化
- 为动植物提供生存所需的水

**水资源是宝贵的！**

地球表面 71% 被水覆盖，但**淡水只占约 2.5%**（大部分是冰川和地下水），人类能直接使用的淡水不到 1%。我国人均水资源仅为世界平均水平的 1/4，节约用水非常重要！

**节约用水的方法**

- 随手关紧水龙头
- 洗菜水可以浇花
- 使用节水型马桶
- 洗澡时间不要太长
- 发现水龙头漏水及时修理`,
