                          solution: '用不同的力弹→振幅改变→**响度**改变（用力弹更响，轻轻弹更轻）；把琴弦调紧→振动频率改变→**音调**改变（弦越紧音调越高）。',
                          tip: '力的大小→振幅→响度；弦的松紧/长短/粗细→频率→音调。这是控制变量法分析问题的典型应用。'
