                          solution: '会看到蜡烛的倒立像。因为光沿直线传播，蜡烛火焰上方的光通过小孔后到达光屏下方，下方的光到达上方，所以成倒立的像。像的大小取决于蜡烛和光屏到小孔的距离。',
                          tip: '小孔成像证明了光沿直线传播。像的清晰度和小孔大小有关——孔太大像会模糊。'
