                          problem: '小华有一根钢针和一根铁钉，但不知道哪个已经被磁化了。你能帮他设计一个方法来判断吗？',
                          solution: '方法一：用钢针/铁钉分别靠近已知磁铁的 N 极和S极，如果一次吸引一次排斥，说明已被磁化（只有磁极间才会排斥）；如果两次都吸引，说明没有被磁化。方法二：悬挂法——用细线悬挂物体，如果自动指向南北，说明已被磁化。',
