                          solution: '湿手触摸开关：水是导体（尤其是含有杂质的水），湿手触摸开关时电流可能通过水传到人体，造成触电。电线着火不能用水灭火：水能导电，用水灭火时电流可能通过水传到人身上，造成触电。应先切断电源，再用干粉灭火器灭火。',
                          tip: '安全用电的核心：避免人体成为电的通路。水+电=非常危险！发现电线着火，第一步永远是切断电源。'
