                          solution: '硬度：玻璃约 5.5，铜钥匙约 3.5，指甲约 2.5。A 能划伤玻璃→硬度 >5.5，可能是石英（7）或更硬；B 能被铜钥匙划伤→硬度 <3.5，可能是方解石（3）；C 能被指甲划伤→硬度 <2.5，可能是滑石（1）或石膏（2）。排序：A > B > C。',
                          tip: '矿物硬度的判断方法：能划伤对方→自己硬度更大。记住几个参照物：指甲(2.5)、铜钥匙(3.5)、玻璃(5.5)、钢刀(6.5)。'
