                        { question: '简答题：为什么科学家通过研究岩石和化石可以了解地球的历史？', answer: '岩石记录了地球的演化过程：岩浆岩反映火山活动，沉积岩中的化石记录了古代生物的种类和生活环境，变质岩反映了地壳运动和高温高压事件。通过研究不同地层的岩石和化石，科学家可以重建地球几十亿年的历史。', explanation: '岩石是地球的"日记"，化石是远古生物的"照片"，两者结合可以还原地球历史。' }
