                        { question: '填空题：土壤主要由______、______、______和______组成。根据颗粒大小，土壤分为______、______和______三种类型。', answer: '矿物质；水；空气；腐殖质（有机质）；沙土；壤土；黏土', explanation: '土壤四成分：矿物质、水、空气、腐殖质。三类型：沙土、壤土、黏土。' },
                        { question: '简答题：蚯蚓为什么被称为"土壤的犁"？它对土壤有什么好处？', answer: '蚯蚓在土壤中钻来钻去，使土壤变得疏松，增加了土壤的透气性和渗水性。蚯蚓吞食土壤中的有机物，排出富含养分的粪便，是天然的肥料。蚯蚓的活动还能帮助混合土壤各层，改善土壤结构。', explanation: '蚯蚓是土壤生态系统的重要成员，对改善土壤结构、增加土壤肥力有重要作用。' }
